insert into ideas (id, category, title, hook, image, video, kind, model, aspect, duration, resolution, motion, prompt, variaciones, fuente, tendencia, oculta, orden) values
  ('granja-dia-en-la-vida', 'Tecnología y granjas', 'Un día en la vida de la caja', 'Del amanecer a la noche sin moverse: la caja sigue trabajando.', null, null, 'video', 'ltx-25', '9:16', 8, '720p', 'fija', 'Plano fijo de una caja de metal llena de iPhones encendidos en filas sobre un escritorio junto a una ventana; la luz de la ventana cambia rápido de día a noche mientras las pantallas siguen encendidas. Zumbido suave de ventiladores. Sin voz.', '[{"titulo":"Con una persona","prompt":"Plano fijo acelerado: una persona entra y sale del cuarto mientras una caja de iPhones en filas sigue trabajando del día a la noche. Sin voz."},{"titulo":"Con voz","prompt":"Plano fijo de una caja de iPhones en filas al atardecer; una voz femenina dice en español latino: \"Mientras tú descansas, ella no\"."},{"titulo":"Lluvia","prompt":"Plano fijo de una caja de iPhones junto a una ventana con [clima: lluvia / neblina], pantallas encendidas. Sonido de lluvia. Sin voz."}]'::jsonb, 'Variación de negocio: un día en la vida de la máquina.', true, true, 1),
  ('selladora-dia-en-la-vida', 'Negocios y máquinas', 'Un día en la vida de la selladora', 'Contada desde la máquina: la serie de negocio que entretiene y vende.', null, null, 'video', 'ltx-25', '9:16', 8, '720p', 'fija', 'Una máquina selladora de vasos de acero inoxidable en un local de jugos sella un vaso tras otro mientras clientes pasan, ritmo alegre, luz de mañana. Sonido de la máquina al sellar. Una voz masculina dice en español latino: "Lunes. Vaso número cien. Sigo invicta".', '[{"titulo":"Hora pico","prompt":"La selladora sella vasos sin parar en hora pico con una fila de clientes. Voz: \"Hora pico. Yo no me canso\"."},{"titulo":"Cierre","prompt":"El local de jugos cierra de noche y la selladora queda sola con la luz encendida. Voz: \"[frase: Mañana seguimos / Otro día invicta]\"."},{"titulo":"Lava cascos","prompt":"Una máquina lava cascos en un mall recibe un casco tras otro. Voz: \"Hoy ya van veinte cascos\"."}]'::jsonb, 'Variación de negocio: un día en la vida de la máquina.', true, true, 2),
  ('mascota-baile', 'Brainrot', 'Tu mascota bailando', 'Sube la foto de tu mascota y hazla bailar. Adjúntala como imagen de referencia.', null, null, 'video', 'veo-fast', '9:16', 6, '720p', 'fija', 'La mascota de la imagen de referencia baila de forma graciosa sobre dos patas en la sala de una casa, moviendo la cabeza al ritmo de una música alegre, cámara fija, luz cálida. Conserva su aspecto y colores.', '[{"titulo":"En la calle","prompt":"La mascota de la imagen de referencia baila en una calle de [ciudad: Lima / Medellín] con gente aplaudiendo alrededor."},{"titulo":"Con lentes","prompt":"La mascota de la imagen de referencia baila con lentes oscuros y cadena dorada bajo luces de discoteca."},{"titulo":"En grupo","prompt":"Tres copias de la mascota de la imagen de referencia bailan coordinadas en un escenario."}]'::jsonb, 'Tendencia: foto a baile (Raindance AI, baile con foto).', true, true, 3),
  ('brainrot-ia-vs-real', 'Brainrot', 'Hecho a mano vs. IA', 'Pantalla dividida: el mismo personaje hecho a mano y con IA. Comenta cuál gana.', null, null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Pantalla dividida por una línea negra vertical, dos estilos muy distintos. Lado izquierdo: un cuy, roedor redondo de orejas muy pequeñas y sin cola, hecho a mano de plastilina marrón con huellas de dedos visibles, sobre cartulina arrugada, que se mueve a saltos torpes de stop-motion. Lado derecho: un cuy realista en animación 3D de cine, con pelo detallado, que baila con fluidez bajo luces de discoteca de colores. No son conejos. Música alegre, sin voz.', '[{"titulo":"Llama","prompt":"Pantalla dividida: una llama de cartón movida a mano a la izquierda y la misma llama en animación 3D a la derecha. Sin voz."},{"titulo":"Dibujo","prompt":"Pantalla dividida: un dibujo infantil de [personaje: un pollo / una papa] a la izquierda y el mismo personaje en animación 3D a la derecha. Sin voz."},{"titulo":"Persona","prompt":"Pantalla dividida: una persona imita un baile con torpeza a la izquierda y un personaje 3D lo hace perfecto a la derecha. Sin voz."}]'::jsonb, 'Tendencia: AI vs Handmade / Dame Hombro, pantalla dividida.', true, true, 4),
  ('perro-cantante', 'Mascotas', 'Tu perro cantando', 'Adjunta la foto de tu perro y hazlo cantar: el formato que más se comparte en familia.', null, null, 'video', 'veo-fast', '9:16', 6, '720p', 'acercamiento', 'El perro de la imagen de referencia canta frente a un micrófono en un pequeño escenario con luces cálidas, mueve la boca con expresión dramática y una voz cómica canta en español: "Te extraño, mi croqueta". Conserva su aspecto y colores.', '[{"titulo":"Reguetón","prompt":"El perro de la imagen de referencia canta reguetón con gorra y cadena: \"Dame [comida: pollo / croqueta], mami\"."},{"titulo":"Balada","prompt":"El perro de la imagen de referencia canta una balada triste bajo la lluvia: \"Volviste sin mi pelota\"."},{"titulo":"Gato","prompt":"El gato de la imagen de referencia canta ópera en un teatro vacío con expresión muy seria."}]'::jsonb, 'Tendencia: Singing Dog AI.', true, true, 5),
  ('canal-sin-rostro', 'Influencers IA', 'Canal sin rostro con voz fija', 'Un presentador virtual y la misma voz en cada video: un canal sin mostrar tu cara.', null, null, 'video', 'ltx-25', '9:16', 8, '720p', 'fija', 'Un presentador virtual latino de 30 años con camisa azul habla a la cámara en un estudio simple con luz suave y dice con voz serena en español latino: "Hoy te cuento tres cosas que nadie te explicó sobre el dinero". Plano medio.', '[{"titulo":"Curiosidades","prompt":"La misma presentadora virtual dice en español latino: \"¿Sabías que tu celular escucha más de lo que crees?\". Plano medio, estudio simple."},{"titulo":"Historias","prompt":"Un narrador virtual de [edad: 40 / 60] años dice en voz baja: \"Esta historia ocurrió en Lima en 1985\". Luz tenue."},{"titulo":"Noticias","prompt":"Una presentadora virtual en un set de noticias dice: \"La tendencia de esta semana te va a sorprender\". Plano medio."}]'::jsonb, 'Tendencia: canales sin rostro con avatar y voz consistentes.', true, true, 6),
  ('persona-baile-foto', 'Influencers IA', 'Foto que se pone a bailar', 'Sube una foto tuya y baila bajo la lluvia. Adjúntala como imagen de referencia.', null, null, 'video', 'veo-fast', '9:16', 6, '720p', 'fija', 'La persona de la imagen de referencia baila con alegría bajo una lluvia suave en una calle de noche con luces reflejadas en el suelo, cámara fija, movimiento fluido. Conserva su cara y su ropa.', '[{"titulo":"En la playa","prompt":"La persona de la imagen de referencia baila en una playa al atardecer con movimiento fluido. Conserva su cara y su ropa."},{"titulo":"En la oficina","prompt":"La persona de la imagen de referencia baila sola en una oficina vacía de noche, con humor. Conserva su cara y su ropa."},{"titulo":"Años 80","prompt":"La persona de la imagen de referencia baila un paso de los años 80 en un set con [luces: neón / bola de disco]. Conserva su cara."}]'::jsonb, 'Tendencia: foto a baile (Raindance AI, baile con foto).', true, true, 7),
  ('bebe-baile', 'Brainrot', 'Bebé animado que baila', 'Un bebé 3D animado con ritmo: tierno, simple y fácil de hacer en serie.', null, null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Un bebé de animación 3D estilo película animada, con pañal y lentes oscuros, baila con mucho ritmo sobre una alfombra de colores en una sala, música alegre, cámara fija, luz cálida. Sin voz.', '[{"titulo":"Con gorra","prompt":"Un bebé de animación 3D con gorra baila en una calle animada con ritmo urbano, cámara fija. Sin voz."},{"titulo":"En grupo","prompt":"Tres bebés de animación 3D bailan coordinados en un escenario de [estilo: teatro / discoteca], cámara fija. Sin voz."},{"titulo":"Fruta","prompt":"Una fruta bebé animada en 3D con pañal baila sobre una mesa de cocina, cámara fija. Sin voz."}]'::jsonb, 'Tendencia: AI Baby Dance, adaptada a un bebé animado.', true, true, 8),
  ('ecom-haul', 'Ecommerce y tiendas', 'Haul: lo que me llegó esta semana', 'Varias compras sobre la cama: entretiene y muestra tu catálogo sin parecer anuncio.', null, null, 'video', 'ltx-25', '9:16', 8, '720p', 'fija', 'Una joven latina sentada en su cama con paquetes abiertos a su alrededor levanta una blusa frente a la cámara y dice con emoción en español latino: "Y esto me costó menos de treinta soles". Luz de ventana, cámara de celular, cuarto real. Sin subtítulos ni logos.', '[{"titulo":"Cocina","prompt":"Una señora latina en su cocina saca utensilios de una caja y dice: \"Miren lo que llegó\". Cámara de celular. Sin subtítulos ni logos."},{"titulo":"Tecnología","prompt":"Un joven latino en su escritorio abre paquetes con audífonos y cables y dice: \"Esto sí valió la pena\". Sin subtítulos ni logos."},{"titulo":"Maquillaje","prompt":"Una joven latina frente a su tocador muestra productos de maquillaje y dice: \"El [producto: labial / rubor] es mi favorito\". Sin subtítulos ni logos."}]'::jsonb, 'Pedido del gerente: ecommerce y realismo LATAM, no sale de una tendencia medida.', true, true, 9),
  ('ecom-problema-solucion', 'Ecommerce y tiendas', 'Problema y solución en un plano', 'Empieza con el problema de tu cliente y termina con tu producto: estructura clásica de anuncio.', null, null, 'video', 'ltx-25', '9:16', 8, '720p', 'fija', 'En una cocina real, una mujer latina intenta abrir un frasco y no puede, resopla, luego usa un abridor pequeño y el frasco se abre de inmediato. Sonríe a la cámara y dice en español latino: "Ojalá lo hubiera comprado antes". Luz natural. Sin subtítulos ni logos.', '[{"titulo":"Cables","prompt":"Un joven enreda los cables de su escritorio, usa un organizador y queda ordenado. Dice: \"Por fin\". Sin subtítulos ni logos."},{"titulo":"Dolor de espalda","prompt":"Un hombre latino se toca la espalda en su silla de oficina, coloca un cojín lumbar y se relaja. Dice: \"Mucho mejor\". Sin subtítulos ni logos."},{"titulo":"Mascota","prompt":"Una mujer quita pelos de perro del sofá sin éxito, usa un rodillo y queda limpio. Dice: \"Así de simple\". Sin subtítulos ni logos."}]'::jsonb, 'Pedido del gerente: ecommerce y realismo LATAM, no sale de una tendencia medida.', true, true, 10),
  ('ecom-venta-en-vivo', 'Ecommerce y tiendas', 'Venta en vivo desde tu tienda', 'El formato de vender en vivo, listo para clips cortos y anuncios.', null, null, 'video', 'ltx-25', '9:16', 8, '720p', 'fija', 'Una vendedora latina de 30 años frente a un celular en un trípode con aro de luz, en su pequeña tienda con ropa colgada detrás, levanta una blusa y dice con energía en español latino: "Quedan solo cinco, escríbeme ahora". Sin subtítulos ni logos.', '[{"titulo":"Maquillaje","prompt":"Una vendedora latina muestra un labial a la cámara en vivo y dice: \"Este se agotó dos veces\". Aro de luz. Sin subtítulos ni logos."},{"titulo":"Zapatillas","prompt":"Un vendedor latino muestra un par de zapatillas en vivo y dice: \"Solo por hoy, envío gratis\". Sin subtítulos ni logos."},{"titulo":"Comida","prompt":"Una señora latina vende [plato: tamales / empanadas] en vivo desde su cocina y dice: \"Recién salidos\". Sin subtítulos ni logos."}]'::jsonb, 'Pedido del gerente: ecommerce y realismo LATAM, no sale de una tendencia medida.', true, true, 11),
  ('latam-historia-emprendedora', 'Negocios y máquinas', 'Empecé vendiendo desde mi cuarto', 'Historia real de emprendedor: el video que genera confianza y comentarios.', null, null, 'video', 'ltx-25', '9:16', 8, '720p', 'fija', 'Una emprendedora latina de 29 años en su pequeño depósito lleno de cajas mira a la cámara y dice con voz cercana en español latino: "Hace un año vendía desde mi cuarto. Hoy envío cien pedidos al día". Cámara en mano, luz natural. Sin subtítulos ni logos.', '[{"titulo":"Food truck","prompt":"Un joven latino frente a su carrito de comida dice: \"Dejé la oficina por este carrito, y no me arrepiento\". Luz de tarde. Sin subtítulos ni logos."},{"titulo":"Señora","prompt":"Una señora latina en su taller de costura dice: \"Empecé con una máquina prestada\". Luz de ventana. Sin subtítulos ni logos."},{"titulo":"Barbero","prompt":"Un barbero latino en su barbería de [ciudad: Lima / Caracas] dice: \"Primero cortaba en la sala de mi mamá\". Sin subtítulos ni logos."}]'::jsonb, 'Pedido del gerente: ecommerce y realismo LATAM, no sale de una tendencia medida.', true, true, 12),
  ('latam-repartidor', 'Ecommerce y tiendas', 'El pedido llega a la puerta', 'El momento de la entrega: transmite que comprarte es seguro.', null, null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Un repartidor latino en moto llega a la puerta de una casa de barrio en Lima, entrega una caja a una clienta sonriente, ella la abre emocionada y dice en español latino: "¡Llegó rapidísimo!". Luz de tarde, cámara en mano. Sin subtítulos ni logos.', '[{"titulo":"Edificio","prompt":"Un repartidor entrega un paquete en la recepción de un edificio y una joven lo recibe. Dice: \"Justo a tiempo\". Sin subtítulos ni logos."},{"titulo":"Provincia","prompt":"Una señora recibe un paquete en la plaza de un pueblo de [lugar: los Andes / la costa] y lo abre feliz. Sin subtítulos ni logos."},{"titulo":"Reacción","prompt":"Primer plano de una persona abriendo una caja en la puerta de su casa, sonrisa y sonido del cartón. Sin subtítulos ni logos."}]'::jsonb, 'Pedido del gerente: ecommerce y realismo LATAM, no sale de una tendencia medida.', true, true, 13),
  ('anime-transformacion', 'Anime', 'Transformación de poder', 'El momento que todos comparten: el personaje despierta su poder.', null, null, 'video', 'veo-fast', '9:16', 6, '720p', 'orbita', 'Animación anime original de acción: un joven latino cierra los ojos en una calle de noche, su cabello se levanta y una energía azul lo envuelve, las piedras flotan a su alrededor, grita con fuerza. Música tensa que crece. Sin subtítulos ni texto.', '[{"titulo":"Oficinista","prompt":"Animación anime original: un oficinista cansado aprieta el puño frente a su jefe y una energía dorada lo envuelve, con humor. Sin texto."},{"titulo":"Abuela","prompt":"Animación anime original: una abuelita tierna se transforma en guerrera con energía [color: roja / verde] en su cocina, con humor. Sin texto."},{"titulo":"Llama","prompt":"Animación anime original: una llama pequeña se transforma en una criatura gigante y brillante en los Andes. Sin texto."}]'::jsonb, 'Pedido del gerente: categoría nueva, no sale de una tendencia medida.', true, true, 14),
  ('navidad-producto-giro', 'Navidad y temporadas', 'Producto girando entre luces navideñas', 'Un anuncio de temporada sin voz, listo para tus historias.', null, null, 'video', 'ltx-25', '9:16', 5, '720p', 'orbita', 'Un frasco de perfume gira lentamente sobre una base de madera con ramas de pino y nieve artificial, luces doradas desenfocadas detrás, la cámara orbita alrededor. Música navideña suave instrumental, sin voz. Sin texto ni logos.', '[{"titulo":"Zapatillas","prompt":"Unas zapatillas giran sobre una caja de regalo roja con luces desenfocadas, música navideña suave. Sin texto ni logos."},{"titulo":"Panetón","prompt":"Un panetón gira sobre una mesa navideña con vapor de chocolate caliente al lado. Sin texto ni logos."},{"titulo":"Joyas","prompt":"Un [joya: collar / reloj] gira dentro de una caja de terciopelo con brillo dorado. Sin texto ni logos."}]'::jsonb, 'Pedido del gerente: categoría nueva, no sale de una tendencia medida.', true, true, 15),
  ('gatito-cocinando', 'Mascotas', 'Gatito cocinando un huevo', 'Video corto y tierno, con sonido de cocina: fácil de hacer en serie.', null, null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Video realista de un gatito naranja diminuto, cría de pocas semanas, con gorro blanco de chef, de pie frente a una sartén pequeña en una cocina casera, moviendo la patita sobre un huevo frito que chisporrotea. Sonido de la sartén y un maullido muy agudo. Luz cálida, cámara fija. Sin texto ni logos.', '[{"titulo":"Panqueques","prompt":"Un gatito diminuto con delantal mira una pila de panqueques más alta que él y le da un golpecito con la patita. Sonido de cocina y un maullido agudo. Sin texto ni logos."},{"titulo":"Café","prompt":"Un gatito diminuto con delantal de barista empuja una taza sobre un mostrador. Sonido de cafetería. Sin texto ni logos."},{"titulo":"Pizza","prompt":"Un gatito [color: gris / blanco] diminuto amasa una masa de pizza con sus patitas sobre una mesa con harina. Sin texto ni logos."}]'::jsonb, 'Pedido directo: gatitos pequeños haciendo cosas tiernas o graciosas. No sale de una tendencia medida.', true, true, 16),
  ('gatito-habla', 'Mascotas', 'Gatito que te dice algo', 'Una voz graciosa en español: el formato que invita a etiquetar a alguien.', null, null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Un gatito naranja diminuto, cría de pocas semanas, sentado en un sofá enorme para él, mira a la cámara y mueve la boca diciendo con voz muy aguda y graciosa en español latino: «Ya sé que comí hace cinco minutos, pero tengo hambre». Sonido ambiente de casa. Video realista, cámara fija. Sin subtítulos ni logos.', '[{"titulo":"Lunes","prompt":"Un gatito diminuto con corbata frente a una laptop dice con voz muy aguda: «Hoy no trabajo, es lunes». Sin subtítulos ni logos."},{"titulo":"Celos","prompt":"Un gatito diminuto mira a la cámara y dice con voz muy aguda: «¿Quién es ese perro en tu foto?». Sin subtítulos ni logos."},{"titulo":"Amor","prompt":"Un gatito diminuto dice con voz muy tierna: «Te quiero, pero [frase: dame atún / abre la puerta]». Sin subtítulos ni logos."}]'::jsonb, 'Pedido directo: gatitos pequeños haciendo cosas tiernas o graciosas. No sale de una tendencia medida.', true, true, 17)
